// GUARD rapido para Evolution inbound
const body = $input.first().json.body;

const event = String(body?.event ?? '');
const eventLower = event.toLowerCase();
const data = body?.data ?? {};
const key = data?.key ?? {};
const messageType = String(data?.messageType ?? data?.type ?? '').toLowerCase();

const fromMe = key?.fromMe ?? true;
const remoteJid = key?.remoteJid ?? null;
const hasJid = !!remoteJid;

const isCallEvent =
  eventLower.includes('call') ||
  messageType.includes('call') ||
  !!data?.call ||
  !!data?.calls ||
  !!body?.call ||
  !!body?.calls;

const isGroup = String(remoteJid ?? '').endsWith('@g.us');

const isValid = (
  event === 'messages.upsert' &&
  fromMe === false &&
  hasJid === true &&
  isCallEvent === false &&
  isGroup === false
);

// ── (B5) Freno anti-bucle ────────────────────────────────────────────
// Silencia 10 min un chat si: más de 12 mensajes en 1 min, o el mismo texto (4+ letras) 3 veces en 2 min.
// Ignora respuestas automáticas de otros negocios. Estado en memoria del workflow (static data).
let loopReason = null;
if (isValid) {
  const store = $getWorkflowStaticData('global');
  const now = Date.now();
  store.rl = store.rl || {};
  for (const k of Object.keys(store.rl)) {
    if (now - (store.rl[k].last ?? 0) > 15 * 60 * 1000) delete store.rl[k];
  }
  const msg = data?.message ?? {};
  const text = String(msg.conversation ?? msg.extendedTextMessage?.text ?? '').trim().toLowerCase().replace(/\s+/g, ' ').slice(0, 200);
  const key = `${body?.instance ?? ''}|${remoteJid}`;
  const st = store.rl[key] ?? { ts: [], texts: [], mutedUntil: 0 };
  st.ts = st.ts.filter(t => now - t < 60 * 1000);
  st.ts.push(now);
  st.texts = st.texts.filter(x => now - x.t < 2 * 60 * 1000);
  if (text.length >= 4) st.texts.push({ t: now, v: text });
  const sameText = text.length >= 4 ? st.texts.filter(x => x.v === text).length : 0;
  if (st.ts.length > 12 || sameText >= 3) st.mutedUntil = now + 10 * 60 * 1000;
  st.last = now;
  store.rl[key] = st;
  const autoReply = /(respuesta autom[aá]tica|mensaje autom[aá]tico|auto-?reply|este es un mensaje autom)/i.test(text);
  if (st.mutedUntil > now) loopReason = 'loop_guard_muted';
  else if (autoReply) loopReason = 'auto_reply';
}

return [{
  json: {
    _is_valid: isValid && !loopReason,
    _skip_reason: loopReason ?? (isCallEvent ? 'call_event' : (isGroup ? 'group_message' : null)),
    _raw_body: body
  }
}];

// Construir una llave de deduplicación ROBUSTA por inbound ANTES de normalize.
// No dependemos solo de message_id porque algunos duplicados de Evolution/Baileys
// pueden llegar con distinto id pero mismo timestamp + contenido.

const item = $input.first().json;
const body = item._raw_body ?? {};
const data = body?.data ?? {};
const msg  = data?.message ?? {};

const instanceName = body?.instance ?? data?.instanceId ?? 'default';
const remoteJid    = data?.key?.remoteJid ?? null;
const messageId    = data?.key?.id ?? null;
const messageType  = String(data?.messageType ?? 'unknown');
const messageTs    = String(data?.messageTimestamp ?? body?.date_time ?? '');

// Extraer una representación estable del contenido antes de normalize
const rawContent =
  msg?.conversation ??
  msg?.extendedTextMessage?.text ??
  msg?.imageMessage?.caption ??
  msg?.videoMessage?.caption ??
  msg?.documentMessage?.caption ??
  msg?.buttonsResponseMessage?.selectedButtonId ??
  msg?.buttonsResponseMessage?.selectedDisplayText ??
  msg?.listResponseMessage?.singleSelectReply?.selectedRowId ??
  msg?.listResponseMessage?.title ??
  msg?.templateButtonReplyMessage?.selectedId ??
  msg?.templateButtonReplyMessage?.selectedDisplayText ??
  msg?.audioMessage?.caption ??
  '';

const normalizedContent = String(rawContent)
  .trim()
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .slice(0, 160);

// Si no hay contenido textual, usar el tipo como huella base
const contentFingerprint = normalizedContent || messageType;

// Hint opcional para trazabilidad
const tenantHint = body?.destination ?? null;

// Llave robusta
const dedupKey = (instanceName && remoteJid && messageTs)
  ? `${instanceName}|${remoteJid}|${messageType}|${messageTs}|${contentFingerprint}`
  : null;

return [{
  json: {
    ...item,
    _instance_name: instanceName,
    _remote_jid: remoteJid,
    _message_id: messageId,
    _message_type: messageType,
    _message_ts: messageTs,
    _tenant_hint: tenantHint,
    _content_fingerprint: contentFingerprint,
    _dedup_key: dedupKey
  }
}];

// Interpretar resultado del claim atómico de deduplicación
const envelope = $('Extraer dedup_key').item.json;
const resp     = $input.first().json;

// Si no hay dedup_key → permitir (no hay cómo deduplicar)
if (!envelope._dedup_key) {
  return [{ json: { ...envelope, _dedup_allow: true, _is_duplicate: false,
                    _dedup_status: 'no_key', _dedup_error: null } }];
}

// PostgREST puede devolver jsonb directo O dentro de array
// Normalizar siempre
let result = resp;
if (Array.isArray(resp)) result = resp[0] ?? {};

// Caso 1: respuesta correcta de la RPC
if (typeof result?.is_duplicate === 'boolean') {
  const isDup = result.is_duplicate;
  return [{ json: { ...envelope, _dedup_allow: !isDup, _is_duplicate: isDup,
                    _dedup_status: isDup ? 'duplicate' : 'new', _dedup_error: null } }];
}

// Caso 2: error de la RPC (fallo de red, permiso, tabla no existe, etc.)
// → FAIL OPEN: dejar pasar el mensaje para no bloquear el sistema
const errMsg = result?.error?.message ?? result?.message ?? result?.hint ?? JSON.stringify(result);
return [{ json: { ...envelope, _dedup_allow: true, _is_duplicate: false,
                  _dedup_status: 'error_open', _dedup_error: errMsg } }];

// Detectar si el inbound es audio / nota de voz sin romper la ruta actual de texto.
const item = $input.first().json;
const body = item._raw_body ?? {};
const data = body?.data ?? {};
const msg  = data?.message ?? {};
const messageType = String(data?.messageType ?? '');

const isAudio =
  /audio|ptt|voice/i.test(messageType) ||
  !!msg?.audioMessage ||
  !!msg?.pttMessage ||
  !!msg?.documentWithCaptionMessage?.message?.audioMessage;

return [{
  json: {
    ...item,
    _message_type: messageType,
    _is_audio: isAudio
  }
}];
